"""Fill text to a width, one paragraph at a time."""


def _paragraphs(text):
    """Yield each paragraph as a list of lines. Blank or whitespace-only lines separate paragraphs."""
    current = []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        elif current:
            yield current
            current = []
    if current:
        yield current


def _fill(words, width):
    """Greedily pack words into lines of at most width characters. A word longer than width gets its own line."""
    lines = []
    line = ""
    for word in words:
        if not line:
            line = word
        elif len(line) + 1 + len(word) <= width:
            line += " " + word
        else:
            lines.append(line)
            line = word
    if line:
        lines.append(line)
    return lines


def wrap(text, width):
    """Return text wrapped to width characters, joined with "\\n" and with no trailing newline.

    Paragraphs are separated by exactly one empty line. Raises ValueError if width < 1.
    """
    if width < 1:
        raise ValueError(f"width must be at least 1, got {width!r}")
    out = []
    for para in _paragraphs(text):
        if out:
            out.append("")
        out.extend(_fill(" ".join(para).split(), width))
    return "\n".join(out)

