class WrapTest(unittest.TestCase):
    def test_greedy_fill(self):
        self.assertEqual(wrap("aaa bbb ccc", 7), "aaa bbb\nccc")
        self.assertEqual(wrap("aaa bbb ccc", 11), "aaa bbb ccc")
        self.assertEqual(wrap("aaa bbb ccc", 3), "aaa\nbbb\nccc")

    def test_whitespace_collapses_inside_paragraph(self):
        self.assertEqual(wrap("a   b\n\tc\r\nd", 10), "a b c d")

    def test_long_word_gets_its_own_line(self):
        self.assertEqual(wrap("hi enormousword yo", 5), "hi\nenormousword\nyo")

    def test_hyphenated_word_is_not_split(self):
        self.assertEqual(wrap("well-known text", 6), "well-known\ntext")

    def test_paragraphs_separated_by_one_blank_line(self):
        self.assertEqual(wrap("one two\n\n\n  \nthree four", 40), "one two\n\nthree four")

    def test_no_leading_or_trailing_blank_lines(self):
        self.assertEqual(wrap("\n\n  one two \n\n", 40), "one two")

